<x-layouts.admin title="Users | FishTrace"><header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-medium text-cyan-700">Access management</p><h1 class="text-3xl font-bold">Users</h1><p class="mt-1 text-slate-500">Manage identities, roles, organizations and account access.</p></div><a href="{{ route('admin.users.create') }}" class="rounded-lg bg-[#075e63] px-4 py-2 font-semibold text-white">Add user</a></header><form class="mt-7 grid gap-3 rounded-xl bg-white p-4 shadow-sm md:grid-cols-5"><input name="q" value="{{ $filters['q'] ?? '' }}" placeholder="Name or email" class="rounded-lg border-slate-300"><select name="status" class="rounded-lg border-slate-300"><option value="">All statuses</option>@foreach(['ACTIVE','DISABLED'] as $status)<option @selected(($filters['status'] ?? '')===$status)>{{ $status }}</option>@endforeach</select><select name="role_id" class="rounded-lg border-slate-300"><option value="">All roles</option>@foreach($roles as $role)<option value="{{ $role->id }}" @selected(($filters['role_id'] ?? '')==$role->id)>{{ $role->name }}</option>@endforeach</select><select name="organization_id" class="rounded-lg border-slate-300"><option value="">All organizations</option>@foreach($organizations as $organization)<option value="{{ $organization->id }}" @selected(($filters['organization_id'] ?? '')===$organization->id)>{{ $organization->name }}</option>@endforeach</select><button class="rounded-lg bg-slate-800 px-4 py-2 text-white">Filter</button></form><section class="mt-6 overflow-hidden rounded-xl bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b bg-slate-50 text-slate-500"><tr><th class="p-4">User</th><th>Roles</th><th>Primary organization</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody>@forelse($users as $user)<tr class="border-b border-slate-100"><td class="p-4"><a href="{{ route('admin.users.show',$user) }}" class="font-semibold text-[#075e63]">{{ $user->name }}</a><div class="text-slate-500">{{ $user->email }}</div></td><td>{{ $user->roles->pluck('name')->join(', ') }}</td><td>{{ optional($user->organizations->firstWhere('pivot.is_primary',true))->name ?? '—' }}</td><td><span class="rounded-full px-2 py-1 text-xs font-semibold {{ $user->status==='ACTIVE' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-200 text-slate-700' }}">{{ $user->isLocked() ? 'LOCKED' : $user->status }}</span></td><td>{{ $user->last_login_at?->format('Y-m-d H:i') ?? 'Never' }}</td><td><a href="{{ route('admin.users.edit',$user) }}" class="text-cyan-700">Edit</a></td></tr>@empty<tr><td colspan="6" class="p-10 text-center text-slate-500">No users match these filters.</td></tr>@endforelse</tbody></table></div><div class="p-4">{{ $users->links() }}</div></section></x-layouts.admin>
